contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint extra) public payable {
        require(extra > 0, "extra must be positive");
        require(address(this).balance >= extra, "not enough balance");
        c.fallback{value: extra}();

        uint cBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        uint amountToWithdraw = cBefore;
        require(thisBefore + amountToWithdraw == address(c).balance + address(this).balance, "conservation precondition");

        bool reverted = false;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && address(this).balance == thisBefore + amountToWithdraw && address(c).balance == cBefore - amountToWithdraw);
    }

    receive() external payable {}
}

