pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        bool revertedWithdrawAll;
        try c.withdrawAll() { revertedWithdrawAll = false; } catch { revertedWithdrawAll = true; }
        bool revertedWithdraw;
        try c.withdraw(amount) { revertedWithdraw = false; } catch { revertedWithdraw = true; }
        bool revertedSendMoney;
        try c.sendMoney(address(this), amount, "") { revertedSendMoney = false; } catch { revertedSendMoney = true; }
        assertTrue(revertedWithdrawAll && revertedWithdraw && revertedSendMoney && address(c).balance == balBefore && c.depositsCount() == depositsBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}

