contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Make msg.sender for the following calls a fresh non-owner address.
        // This contract is the deployer/owner; call through a low-level call from a new address.
        address nonOwner = address(uint160(uint(keccak256(abi.encodePacked(address(this))))));
        bool revertedWithdrawAll;
        {
            (bool ok, ) = nonOwner.call(abi.encodeWithSignature("withdrawAll()"));
            revertedWithdrawAll = !ok;
        }
        bool revertedWithdraw;
        {
            (bool ok, ) = nonOwner.call(abi.encodeWithSignature("withdraw(uint256)", amount));
            revertedWithdraw = !ok;
        }
        bool revertedSendMoney;
        {
            (bool ok, ) = nonOwner.call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", address(this), amount, ""));
            revertedSendMoney = !ok;
        }

        assert(revertedWithdrawAll && revertedWithdraw && revertedSendMoney && address(c).balance == balBefore && c.depositsCount() == depositsBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Setup: ensure the test contract (owner) seeds some balance and deposits on c.
        c.fallback{value: amount}();

        uint balMid = address(c).balance;
        uint depositsMid = c.depositsCount();
        assert(balMid == balBefore + amount);
        assert(depositsMid == depositsBefore + 1);

        // Create a fresh non-owner account via a contract wrapper.
        NonOwnerCaller noc = new NonOwnerCaller(c);

        bool revertedWithdrawAll;
        try noc.callWithdrawAll() { revertedWithdrawAll = false; } catch { revertedWithdrawAll = true; }

        bool revertedWithdraw;
        try noc.callWithdraw(amount) { revertedWithdraw = false; } catch { revertedWithdraw = true; }

        bool revertedSendMoney;
        try noc.callSendMoney(address(this), amount, "") { revertedSendMoney = false; } catch { revertedSendMoney = true; }

        assert(revertedWithdrawAll && revertedWithdraw && revertedSendMoney && address(c).balance == balMid && c.depositsCount() == depositsMid);
    }

    receive() external payable {}
}

contract NonOwnerCaller {
    C c;
    constructor(C _c) { c = _c; }
    function callWithdrawAll() external { c.withdrawAll(); }
    function callWithdraw(uint v) external { c.withdraw(v); }
    function callSendMoney(address t, uint v, bytes calldata d) external { c.sendMoney(t, v, d); }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount > 0);

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Setup: seed C with Ether and increment depositsCount via a benign fallback call
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        uint balMid = address(c).balance;
        uint depositsMid = c.depositsCount();

        // Simulate a non-owner caller by having a separate contract call the owner-only functions
        NonOwnerCaller noc = new NonOwnerCaller(c);

        bool revertedWithdrawAll;
        try noc.callWithdrawAll() { revertedWithdrawAll = false; } catch { revertedWithdrawAll = true; }

        bool revertedWithdraw;
        try noc.callWithdraw(amount) { revertedWithdraw = false; } catch { revertedWithdraw = true; }

        bool revertedSendMoney;
        try noc.callSendMoney(address(this), amount, "") { revertedSendMoney = false; } catch { revertedSendMoney = true; }

        assert(
            revertedWithdrawAll &&
            revertedWithdraw &&
            revertedSendMoney &&
            address(c).balance == balMid &&
            c.depositsCount() == depositsMid
        );
    }

    receive() external payable {}
}

contract NonOwnerCaller {
    C c;
    constructor(C _c) { c = _c; }
    function callWithdrawAll() external { c.withdrawAll(); }
    function callWithdraw(uint v) external { c.withdraw(v); }
    function callSendMoney(address t, uint v, bytes calldata d) external { c.sendMoney(t, v, d); }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint amount, bytes memory data) public payable {
        require(address(this).balance >= amount, "Insufficient test contract balance");

        uint beforeOwner = uint(uint160(c.owner()));
        uint beforeCount = c.depositsCount();

        bool reverted;
        try c.sendMoney{value: amount}(target, 0, data) {
