        } catch {
            reverted = true;
        }

        uint afterOwner = uint(uint160(c.owner()));
        uint afterCount = c.depositsCount();

        assert(!reverted || (afterOwner == beforeOwner && afterCount == beforeCount));
    }

    receive() external payable {}
}

